import numpy as np

def select_next_node(current_node, depot, unvisited_nodes, rest_capacity, demands, distance_matrix):
    """Return an int from unvisited_nodes (or 0 to return to depot early when current_node != 0)."""
    unvisited_nodes = np.asarray(unvisited_nodes, dtype=np.int64)
    if unvisited_nodes.size == 0:
        return int(depot)

    scale = float(np.mean(distance_matrix[depot, 1:]))
    if not np.isfinite(scale) or scale <= 0:
        scale = 1.0

    d_cur = distance_matrix[current_node, unvisited_nodes].astype(np.float64)
    d_depot_next = distance_matrix[depot, unvisited_nodes].astype(np.float64)
    d_cur_depot = float(distance_matrix[current_node, depot])

    # Depot savings: how much closer the customer is to the depot than current node is.
    savings = (d_cur_depot - d_cur) / scale
    # Normalized nearest distance.
    near = d_cur / scale
    # Normalized distance from depot to candidate.
    depot_near = d_depot_next / scale

    cap_ratio = rest_capacity / max(1e-12, float(np.mean(demands[1:])) )

    # Regime switch based on capacity fill level.
    if cap_ratio >= 2.5:
        # Plenty of capacity: prefer nearest customers, slight savings bonus.
        score = -near + 0.15 * savings
    elif cap_ratio >= 0.75:
        # Balanced: blend savings and proximity.
        score = 0.6 * savings - 0.6 * near + 0.1 * depot_near
    else:
        # Low capacity: strong savings and depot proximity preference.
        score = 1.0 * savings - 0.3 * near + 0.4 * depot_near

    # Prefer larger demands slightly to avoid leaving fragments.
    demand_bonus = 0.05 * (demands[unvisited_nodes].astype(np.float64) / max(1e-12, float(np.mean(demands[1:]))))
    score = score + demand_bonus

    # Voluntary early return: if current node is not depot and best candidate is far.
    if current_node != depot:
        best_idx = int(np.argmax(score))
        best_near = float(near[best_idx])
        # If rest capacity is very low relative to average demand, or best candidate far, return.
        if cap_ratio < 0.35 and best_near > 1.0:
            return int(depot)
        if best_near > 2.5 and d_cur_depot / scale < best_near * 0.6:
            return int(depot)

    best_idx = int(np.argmax(score))
    return int(unvisited_nodes[best_idx])
